import { useState } from "react";
import "./AdoptionSearchBar.css";

const AdoptionSearchBar = () => {
  const [searchTerm, setSearchTerm] = useState(""); // حالة لتخزين النص المدخل

  const handleInputChange = (event) => {
    setSearchTerm(event.target.value); // تحديث قيمة النص المدخل
  };

  return (
    <div className="search-container">
      <input
        type="text"
        placeholder="Search for an animal..."
        id="search-box"
        value={searchTerm} // ربط المدخل مع حالة searchTerm
        onChange={handleInputChange} // تحديث حالة searchTerm عند التغيير
      />
      <button type="button" className="adoption-button">
        Search
      </button>
    </div>
  );
};

export default AdoptionSearchBar;
